export default function telegramJsonProgress({ chatId, parts, previousState, message }) {
  if (typeof chatId !== 'string' || !/^[1-9][0-9]*$/.test(chatId) || !Array.isArray(parts) || !parts.length) throw new Error('Expected JSON parts and the original private sender');
  let state;
  if (previousState == null) state = { index: 0, receipts: [] };
  else {
    if (!Number.isInteger(previousState.index) || previousState.index < 1 || previousState.index > parts.length || !Array.isArray(previousState.receipts) || previousState.receipts.length !== previousState.index - 1) throw new Error('Invalid JSON echo progress');
    if (!message || !Number.isSafeInteger(message.messageId) || message.messageId <= 0 || (message.chat?.type !== 'private' || String(message.chat?.id) !== chatId) || message.text !== parts[previousState.index - 1].text) throw new Error('Telegram did not confirm the complete JSON part in the original sender’s private chat; sending may already have occurred');
    state = { index: previousState.index, receipts: [...previousState.receipts, message] };
  }
  const part = parts[state.index];
  if (part == null) return { state, more: false, html: '<pre>{}</pre>', count: state.receipts.length };
  if (typeof part.html !== 'string' || part.html.length < 1 || part.html.length > 4096 || typeof part.text !== 'string' || !part.text) throw new Error('Invalid JSON echo part');
  return { state: { index: state.index + 1, receipts: state.receipts }, more: true, html: part.html, count: state.receipts.length };
}
